-- Following is independent of community membership. Only the owner can read
-- or change their subscriptions; notifications are generated by the database.
CREATE TABLE IF NOT EXISTS public.community_follows (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, community_id)
);
CREATE INDEX IF NOT EXISTS community_follows_target ON public.community_follows(community_id);
CREATE TABLE IF NOT EXISTS public.thread_follows (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  post_id uuid NOT NULL REFERENCES public.forum_posts(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, post_id)
);
CREATE INDEX IF NOT EXISTS thread_follows_target ON public.thread_follows(post_id);
ALTER TABLE public.community_follows ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.thread_follows ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS own_follows ON public.community_follows;
CREATE POLICY own_follows ON public.community_follows TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
DROP POLICY IF EXISTS own_follows ON public.thread_follows;
CREATE POLICY own_follows ON public.thread_follows TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
GRANT SELECT, INSERT, DELETE ON public.community_follows, public.thread_follows TO authenticated;
GRANT ALL ON public.community_follows, public.thread_follows TO service_role;

-- A publication ledger prevents repeated alerts if approval is toggled later.
CREATE TABLE IF NOT EXISTS public.follow_notified_posts (
  post_id uuid PRIMARY KEY REFERENCES public.forum_posts(id) ON DELETE CASCADE
);
ALTER TABLE public.follow_notified_posts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.follow_notified_posts FROM anon, authenticated;
GRANT ALL ON public.follow_notified_posts TO service_role;
-- Existing posts are already published: edits must not send retroactive alerts.
INSERT INTO public.follow_notified_posts(post_id)
SELECT id FROM public.forum_posts WHERE is_approved = true
ON CONFLICT DO NOTHING;

CREATE OR REPLACE FUNCTION public.notify_community_followers()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF NEW.is_approved IS DISTINCT FROM true OR COALESCE(NEW.is_deleted, false) THEN RETURN NEW; END IF;
  INSERT INTO public.follow_notified_posts(post_id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN NEW; END IF;
  INSERT INTO public.notifications(user_id, title, body, data)
  SELECT f.user_id, 'New post in ' || c.name, LEFT(NEW.title, 140),
    jsonb_build_object('type', 'community_post', 'post_id', NEW.id, 'from_user', NEW.user_id,
      'community_id', NEW.community_id, 'link', '/community/forum/' || NEW.id)
  FROM public.community_follows f JOIN public.communities c ON c.id = f.community_id
  WHERE f.community_id = NEW.community_id AND f.user_id <> NEW.user_id;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.notify_community_followers() FROM PUBLIC;
DROP TRIGGER IF EXISTS notify_community_followers ON public.forum_posts;
CREATE TRIGGER notify_community_followers AFTER INSERT OR UPDATE OF is_approved ON public.forum_posts
  FOR EACH ROW EXECUTE FUNCTION public.notify_community_followers();

CREATE OR REPLACE FUNCTION public.notify_thread_followers()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE parent_author uuid;
BEGIN
  IF NEW.entity_type <> 'forum_post' OR COALESCE(NEW.is_deleted, false) THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.forum_posts WHERE id::text = NEW.entity_id
    AND is_approved = true AND NOT COALESCE(is_deleted, false)) THEN RETURN NEW; END IF;
  SELECT user_id INTO parent_author FROM public.comments WHERE id = NEW.parent_id;
  INSERT INTO public.notifications(user_id, title, body, data)
  SELECT f.user_id, 'New reply in a thread you follow',
    CASE WHEN NEW.is_spoiler THEN 'Spoiler reply' ELSE
      COALESCE(NULLIF(LEFT(regexp_replace(NEW.content, '<[^>]*>', '', 'g'), 140), ''), 'Sent an attachment') END,
    jsonb_build_object('type', 'thread_reply', 'post_id', f.post_id, 'comment_id', NEW.id, 'from_user', NEW.user_id,
      'link', '/community/forum/' || f.post_id || '#comment-' || NEW.id)
  FROM public.thread_follows f
  WHERE f.post_id::text = NEW.entity_id AND f.user_id <> NEW.user_id
    -- Existing reply and mention triggers already notify these recipients.
    AND f.user_id IS DISTINCT FROM parent_author
    AND NOT (f.user_id = ANY(COALESCE(NEW.mentions, ARRAY[]::uuid[])));
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.notify_thread_followers() FROM PUBLIC;
DROP TRIGGER IF EXISTS notify_thread_followers ON public.comments;
CREATE TRIGGER notify_thread_followers AFTER INSERT ON public.comments
  FOR EACH ROW EXECUTE FUNCTION public.notify_thread_followers();
